const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2019;
  const startDate = `${year}-01-01`;
  const endDate = `${year}-12-31`;
  const tempThresholdCelsius = 75;

  // Find the Sonoran Desert ecoregion from the WWF dataset.
  const ecoregions = ee.FeatureCollection('WWF/Terrestrial_Ecoregions');
  const sonoranDesert = ecoregions.filter(ee.Filter.eq('ECO_NAME', 'Sonoran desert')).geometry();

  if (!sonoranDesert.getInfo()) {
      console.log("Could not find the 'Sonoran desert' ecoregion.");
      console.log("A"); // Likely a name mismatch, but let's be robust
      return;
  }

  // 2. Data Acquisition & Check
  const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .select('LST_Day_1km');

  const collectionSize = modisLST.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No MODIS LST images found for ${year}.`);
    console.log("C1");
    return;
  }
  console.log(`Source Images Found: ${collectionSize}`);

  // 3. Processing: Create a max composite and convert to Celsius
  // The LST band is in Kelvin with a scale factor of 0.02.
  // Formula: Celsius = (Kelvin * 0.02) - 273.15
  const maxLSTKelvin = modisLST.max();
  const maxLSTCelsius = maxLSTKelvin.multiply(0.02).subtract(273.15);

  // 4. Calculation
  const stats = maxLSTCelsius.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: sonoranDesert,
    scale: 1000, // MODIS native resolution
    maxPixels: 1e9
  });

  const maxTemp = stats.get('LST_Day_1km_max').getInfo();
  const pixelCount = stats.get('LST_Day_1km_count').getInfo();

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log("No valid pixels found within the Sonoran Desert geometry for the date range.");
    console.log("C2");
    return;
  }

  if (maxTemp === null || typeof maxTemp === 'undefined') {
    console.log("Calculation failed: The maximum temperature could not be computed.");
    console.log("C3");
    return;
  }

  console.log(`Sonoran Desert, ${year}`);
  console.log(`Valid Pixels Analyzed: ${pixelCount}`);
  console.log(`Max Land Surface Temp: ${maxTemp.toFixed(2)} C`);
  console.log(`Threshold for 'Yes': > ${tempThresholdCelsius} C`);

  if (maxTemp > tempThresholdCelsius) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
